/// Status BAD_REQUEST:
/// Invalid characters in "user" were provided.
#[derive(Debug, Serialize, Deserialize, Clone, PartialEq, Eq)]
pub enum HelloUserError {
    InvalidCharacters,
}

impl Display for HelloUserError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let message = match self {
            Self::InvalidCharacters => "Invalid characters",
        };
        f.write_str(message)
    }
}

impl StatusCoded for HelloUserError {
    fn status_code(&self) -> StatusCode {
        match self {
            Self::InvalidCharacters => StatusCode::BAD_REQUEST,
        }
    }
}

