#[async_trait(?Send)]
pub trait ApiService<S>
where
    S: Send + Sync + 'static,
{
    /// Service Health check
    async fn health(
        data: web::Data<S>,
    ) -> web::Json<HealthResponse>;
    /// Returns a greeting to the user!
    async fn hello_user(
        data: web::Data<S>,
        path: web::Path<HelloUserPath>,
    ) -> Result<web::Json<String>, Detailed<HelloUserError>>;
}

// Run service function (+ helper functions)
// -----------------------------------------
static DOCS_OPENAPI: &str = include_str!("openapi.yaml");
static DOCS_HTML: &str = include_str!("docs.html");
async fn openapi() -> String {
    DOCS_OPENAPI.to_string()
}
async fn docs() -> HttpResponse {
    HttpResponse::build(StatusCode::OK)
        .content_type("text/html; charset=utf-8")
        .body(DOCS_HTML)
}
async fn to_v1_docs() -> HttpResponse {
    HttpResponse::build(StatusCode::TEMPORARY_REDIRECT)
        .append_header(("Location", "v1/docs"))
        .body("")
}
async fn to_docs() -> HttpResponse {
    HttpResponse::build(StatusCode::TEMPORARY_REDIRECT)
        .append_header(("Location", "docs"))
        .body("")
}

// Tells that service is alive
async fn health() -> HttpResponse {
    HttpResponse::Ok().finish()
}


/// Just make scope - can be used for manual server creation
/// And to combine with other scopes
pub fn make_scope<T, S>(prometheus: PrometheusMetrics) -> actix_web::Scope
where
    T: ApiService<S> + 'static,
    S: Send + Sync + 'static,
{
    use web::{delete, get, post};

    let api = web::scope("")
        .route("/health", get().to(T::health))
        .route("/hello/{user}", get().to(T::hello_user))
        .route("/v1/health", get().to(T::health))
        .route("/v1/hello/{user}", get().to(T::hello_user))
        .wrap(prometheus);

    web::scope("")
        // Aux services
        .route("/health", get().to(health))
        // Static paths
        .route("/", get().to(to_docs))
        .route("/docs", get().to(docs))
        .route("/openapi.yaml", get().to(openapi))
        .route("/v1", get().to(to_v1_docs))
        .route("/v1/", get().to(to_docs))
        .route("/v1/docs", get().to(docs))
        .route("/v1/openapi.yaml", get().to(openapi))
        // Server routes
        .service(api)
}
